def next_recovery(task):
    if task.get("state") == "running":
        return "wait"
    elif task.get("state") == "queued":
        return "retry"
    elif task.get("state") == "failed":
        if task.get("attempts", 0) < task.get("max_attempts", 3):
            return "retry"
        else:
            return "escalate"
    else:
        raise ValueError("Unknown state")

from recovery import next_recovery

def test_running_state():
    task = {"state": "running"}
    assert next_recovery(task) == "wait"

def test_queued_state():
    task = {"state": "queued"}
    assert next_recovery(task) == "retry"

def test_failed_with_attempts():
    task = {"state": "failed", "attempts": 1, "max_attempts": 3}
    assert next_recovery(task) == "retry"

def test_failed_max_attempts():
    task = {"state": "failed", "attempts": 3, "max_attempts": 3}
    assert next_recovery(task) == "escalate"

def test_unknown_state():
    task = {"state": "unknown"}
    try:
        next_recovery(task)
        assert False, "Should have raised ValueError"
    except ValueError:
        pass

def test_immutability():
    task = {"state": "running"}
    original = task.copy()
    next_recovery(task)
    assert task == original

if __name__ == "__main__":
    test_running_state()
    test_queued_state()
    test_failed_with_attempts()
    test_failed_max_attempts()
    test_unknown_state()
    test_immutability()
    print("All tests passed")
